<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRelyingPartyVO;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;

trait PlatformIdentityRelyingPartyAttributeHolder
{
    protected PlatformIdentityRelyingPartyVO|RelyingPartyRef|null $relyingParty = null;
    protected bool $relyingPartyAssigned = false;

    public function getRelyingPartyOrDefault(?PlatformIdentityRelyingPartyVO $relyingParty): ?PlatformIdentityRelyingPartyVO
    {
        return $this->relyingPartyAssigned ? ($this->relyingParty !== null ? PlatformIdentityRelyingPartyVO::from($this->relyingParty) : null) : $relyingParty;
    }
    public function relyingParty(PlatformIdentityRelyingPartyVO|RelyingPartyRef|null $relyingParty): static
    {
        $this->relyingParty = $relyingParty;
        $this->relyingPartyAssigned = true;
        return $this;
    }
    public function getRelyingParty(): ?RelyingPartyRef
    {
        return is_a($this->relyingParty, PlatformIdentityRelyingPartyVO::class) ? $this->relyingParty?->value() : $this->relyingParty;
    }
    public function unsetRelyingParty(): static
    {
        $this->relyingParty = null;
        $this->relyingPartyAssigned = false;
        return $this;
    }
    protected function withDefaultRelyingParty(): void
    {
    }
    protected function withAssertedRelyingPartyRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->relyingPartyAssigned = $this->relyingPartyAssigned) {
            $value->relyingParty = PlatformIdentityRelyingPartyVO::tryFrom($this->relyingParty, $errorsList);
        }
    }
}
